#include <algorithm>
#include <cstdio>
#include <queue>
#define Maxn 5500
#define Maxm 35500
#define INF 1000000000
using namespace std;
struct Link
{int nxt,t,c,l;}g[Maxm];
int first[Maxn],tl=1;
void connect(int f,int t,int c,int cost){
  g[++tl]=(Link){first[f],t,c,cost};first[f]=tl;
  g[++tl]=(Link){first[t],f,0,-cost};first[t]=tl;
}
int S,T,pre[Maxn],lp[Maxn],flow[Maxn],dis[Maxn];
bool inq[Maxn];
queue<int> q;
int spfa()
{
  for (int i=1;i<=T;i++)
    {dis[i]=INF;flow[i]=0;}
  flow[S]=INF;dis[S]=0;
  q.push(S);inq[S]=true;
  while(!q.empty()){
    int u=q.front();
    inq[u]=false;q.pop();
    for (int i=first[u],v;i;i=g[i].nxt)
      if (g[i].c&&dis[v=g[i].t]>dis[u]+g[i].l){
        dis[v]=dis[u]+g[i].l;
        flow[v]=min(flow[u],g[i].c);
        lp[v]=i;pre[v]=u;
        if (!inq[v]){inq[v]=true;q.push(v);}
     }
  }return flow[T];
}
int n,m,k,C,D,pl[105][105],st[105][105];
struct Data
{int f,t;}s[105];
#define P(x,y) ((x)*n+(y))
int main()
{
  scanf("%d%d%d%d%d",&n,&m,&k,&C,&D);
  S=P(n+k,n)+1;T=S+2;
  connect(P(0,1),T,INF,0);
  for (int i=1,p;i<=k;i++){
    scanf("%d",&p);
    connect(S,P(0,p),1,0);
  }for (int i=1;i<=m;i++){
    scanf("%d%d",&s[i*2].f,&s[i*2].t);
    s[i*2-1]=(Data){s[i*2].t,s[i*2].f};
  }m*=2;
  for (int t=1;t<=n+k;t++){
    for (int i=1;i<=n;i++)
      connect(P(t-1,i),P(t,i),INF,0);
    for (int i=1;i<=m;i++){
      connect(P(t-1,s[i].f),P(t,s[i].t),1,D);
      pl[t][i]=tl;st[t][i]=1;
    }connect(P(t,1),T,INF,t*C);
  }
  int total_flow=0, total_cost=0;
  while(int flow_now=spfa()){
    int u=T;
    while(u!=S){
      int last=pre[u];
      g[lp[u]].c-=flow_now;
      g[lp[u]^1].c+=flow_now;
      u=last;
    }
    total_cost+=dis[T]*flow_now;
    for (int t=1;t<=n+n;t++)
      for (int i=1;i<=m;i++)
        if (g[pl[t][i]].c){
          st[t][i]++;
          connect(P(t-1,s[i].f),P(t,s[i].t),1,D*(st[t][i]*2-1));
          pl[t][i]=tl;
        }
  }printf("%d\n",total_cost);
  return 0;
}
